#[allow(unused_variables)]
fn field_pos(ty: &str, f: &str) -> usize {
    match (ty, f) {
        ("AluResult", "result") => 0,
        ("AluResult", "zero") => 1,
        ("AluResult", "carry") => 2,
        ("AluResult", "negative") => 3,
        ("AluResult", "overflow") => 4,
        ("RippleCarryResult", "sum") => 0,
        ("RippleCarryResult", "carry_out") => 1,
        ("RippleCarryResult", "overflow") => 2,
        _ => panic!("no such field"),
    }
}

#[allow(unused_variables, unused_mut)]
fn op_half_adder(_w: &[u64], args: &[V], fault: Fault) -> V {
    let fault = fault_for("half_adder", fault);
    let p0 = host::<u8>(args[0].int());
    let p1 = host::<u8>(args[1].int());
    let v: V = match contained(|| half_adder(p0, p1)) {
        Some(r) => V::Ok(Box::new({ let t1 = r; V::Tup(vec![V::Fixed(F::U8, (t1.0) as i128), V::Fixed(F::U8, (t1.1) as i128)]) })),
        None if fault == Fault::MissingError => V::Ok(Box::new(domain_take(Ty::Tuple(&[Ty::Fx(F::U8), Ty::Fx(F::U8)]), 1).remove(0))),
        None => V::Err("INVALID_INPUT".into()),
    };
    match fault {
        Fault::DropConsumed => fault_drop_consumed(v),
        Fault::OffByOneConsumed => fault_off_by_one_consumed(v),
        Fault::SwapComponents => fault_swap_components(v),
        _ => v,
    }
}

