#[allow(unused_variables, unused_mut)]
fn op_alu(_w: &[u64], args: &[V], fault: Fault) -> V {
    let fault = fault_for("alu", fault);
    let p0 = args[0].bytes();
    let p1 = args[1].bytes();
    let p2 = match args[2].ctor() { 0 => arithmetic::AluOp::Add {  }, 1 => arithmetic::AluOp::Sub {  }, 2 => arithmetic::AluOp::And {  }, 3 => arithmetic::AluOp::Or {  }, 4 => arithmetic::AluOp::Xor {  }, 5 => arithmetic::AluOp::Not {  }, _ => unreachable!("constructor index") };
    let v: V = match contained(|| alu(p0, p1, p2)) {
        Some(r) => V::Ok(Box::new({ let s1 = r; V::Con("AluResult", 0, "AluResult", vec![V::Bytes((s1.result).to_vec()), V::Bool(s1.zero), V::Bool(s1.carry), V::Bool(s1.negative), V::Bool(s1.overflow)]) })),
        None if fault == Fault::MissingError => V::Ok(Box::new(domain_take(Ty::Data("AluResult", &[("AluResult", &[Ty::Bytes, Ty::Bool, Ty::Bool, Ty::Bool, Ty::Bool])]), 1).remove(0))),
        None => V::Err("INVALID_INPUT".into()),
    };
    v
}

